() => {
  const [message, setMessage] = useState('Default message')
  useEffect(() => {
    const interval = setInterval(() => {
      setMessage(`Last updated at ${new Date().toLocaleTimeString()}`)
    }, 5000)
    return () => {
      clearInterval(interval)
    }
  }, [])
  return <AriaAlert>{message}</AriaAlert>
}

